"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[849],{86164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"DocsSidebar":[{"type":"link","label":"Introduction","href":"/docs/getting-started/intro","docId":"getting-started/intro","unlisted":false},{"type":"category","label":"Concepts","items":[{"type":"link","label":"Device Binding","href":"/docs/concepts/device-binding","docId":"concepts/device-binding","unlisted":false},{"type":"link","label":"Devices Screen","href":"/docs/concepts/devices-screen","docId":"concepts/devices-screen","unlisted":false},{"type":"link","label":"Spaces","href":"/docs/concepts/spaces","docId":"concepts/spaces","unlisted":false},{"type":"link","label":"Roles & Permissions","href":"/docs/concepts/roles-permissions","docId":"concepts/roles-permissions","unlisted":false},{"type":"link","label":"How Instant Connect Works","href":"/docs/concepts/dasset-instant-connect","docId":"concepts/dasset-instant-connect","unlisted":false},{"type":"link","label":"DASSET AI","href":"/docs/concepts/dasset-ai","docId":"concepts/dasset-ai","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"User Guide","items":[{"type":"link","label":"Windows & macOS","href":"/docs/user-guide/pc-mac","docId":"user-guide/pc-mac","unlisted":false},{"type":"link","label":"Android & iOS","href":"/docs/user-guide/mobile","docId":"user-guide/mobile","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"OEMs","items":[{"type":"link","label":"DASSET for OEMs","href":"/docs/oem-odm/oem-opportunity","docId":"oem-odm/oem-opportunity","unlisted":false},{"type":"link","label":"DASSET Software Platform","href":"/docs/oem-odm/oem-software-platform","docId":"oem-odm/oem-software-platform","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"FAQ","href":"/docs/faq/faqs","docId":"faq/faqs","unlisted":false},{"type":"category","label":"Troubleshooting","items":[{"type":"link","label":"Connectivity Errors","href":"/docs/troubleshooting/connectivity","docId":"troubleshooting/connectivity","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"Privacy Policy","href":"/docs/privacy-policy/","docId":"privacy-policy/privacy-policy","unlisted":false}]},"docs":{"concepts/dasset-ai":{"id":"concepts/dasset-ai","title":"DASSET AI","description":"Public Cloud AI Services","sidebar":"DocsSidebar"},"concepts/dasset-instant-connect":{"id":"concepts/dasset-instant-connect","title":"How Instant Connect Works","description":"Overview","sidebar":"DocsSidebar"},"concepts/device-binding":{"id":"concepts/device-binding","title":"Device Binding","description":"New DASSET Data Hubs are shipped ready to be setup by the owner of the device. The owner has complete administrative control over how the device is used, including who else may or may not be able to access content on the Data Hub.  Owners of a Data Hub are bound to the device through a process called binding. Only one user account can be bound as the Owner of a Data Hub.","sidebar":"DocsSidebar"},"concepts/devices-screen":{"id":"concepts/devices-screen","title":"Devices Screen","description":"After logging-in to your DASSET user account, you are presented with the Devices Screen, where you manage all aspects of your DASSET user account, such as connecting to devices and changing your account information.","sidebar":"DocsSidebar"},"concepts/roles-permissions":{"id":"concepts/roles-permissions","title":"Roles & Permissions","description":"DASSET uses Role-Based Access Control (RBAC) to control what permissions users of the Data Hub can, or cannot, do.  Each user of the system is assigned a role, either automatically by the system, or specifically by the Owner of the device.","sidebar":"DocsSidebar"},"concepts/spaces":{"id":"concepts/spaces","title":"Spaces","description":"The exposure of the file system in DASSET is designed to present data to the user that only they have access to.  Rather than combing through a tree of file folders containing both user and system files, DASSET easily organizes user\'s data into Spaces.  Spaces are logical representations of data on the Data Hub.","sidebar":"DocsSidebar"},"faq/faqs":{"id":"faq/faqs","title":"FAQs","description":"What exactly is a DASSET Data Hub?","sidebar":"DocsSidebar"},"features/account-settings":{"id":"features/account-settings","title":"Account Settings","description":"Your DASSET User Account can be used on several DASSET Data Hubs, rather than having to create new accounts for each Data Hub you have been invited to join.  If you only have 1 Data Hub, then the relationship between Account and Data Hub is 13."},"features/apps/album-backup":{"id":"features/apps/album-backup","title":"Album Back-up","description":"Bringing all of your data together in a single, secure location is a fundamental tenet of DASSET.  Album Backup provides an easy way to ensure the photos on your phone, tablet or computer, are easily and automatically backed-up to your DASSET Data Hub."},"features/apps/contacts-backup":{"id":"features/apps/contacts-backup","title":"Contacts Back-Up","description":"In addition to data we think of as files and photos, DASSET also offers the ability to back-up other types of data that is important to you - like your contacts on your phone.  Contacts Backup provides a simple way to back-up, and restore, your contacts."},"features/apps/de-duplication":{"id":"features/apps/de-duplication","title":"File De-Duplication","description":"When bringing all of your data together from multiple devices and clouds, it\'s likely that you will have the same file from these locations, copied multiple times to your Data Hub.  Finding these files on your own, and deciding which ones to keep vs. delete can be daunting."},"features/apps/dlna":{"id":"features/apps/dlna","title":"Streaming Media (DLNA)","description":"Your DASSET Data Hub can act as a media server for your home or office, giving you the ability to stream content such as videos and audio to TVs, consoles and stereos that support the DLNA protocol."},"features/apps/external-storage":{"id":"features/apps/external-storage","title":"External Storage","description":"Your DASSET Data Hub has the ability to view and manage data that reside on storage devices that can connect to your Data Hub via USB.  These include portable HDDs, SSDs and thumbdrives.  Rather than copying the contents of these storage devices to your computer first, and then transferring them to your Data Hub, you can simply copy them directly using External Storage."},"features/apps/recycle":{"id":"features/apps/recycle","title":"Recycle Bin","description":"Like most operating systems, DASSET comes with the ability to restore files accidentally deleted by the user.  The Recycle Bin is where all files deleted on the system are placed, giving you the ability to undo those \\"Oops\\" moments of deleting a file inadvertently."},"features/apps/samba":{"id":"features/apps/samba","title":"LAN Access (Samba)","description":"In addition to accessing files on your Data Hub through the DASSET application, the ability to do so directly from a device that supports the SMB networking protocol), such as Windows and Linux/Unix-based Operating Systems like Android and Apple MacOS and iOS.  Samba in DASSET is an implementation of the SMB networking protocol, making it easy to establish file-sharing between your Windows, MacOS or mobile phone and a DASSET Data Hub."},"features/homescreen":{"id":"features/homescreen","title":"Home Screen","description":"After logging into your DASSET user account and connecting to a Data Hub, you are presented with the Home Screen.  The Home Screen is your one-stop shop for accessing all of the functionality of DASSET on the Data Hub you are connected to.  For example, connecting to a Data Hub that you have been invited to join may have a slightly different Home Screen than when you connect to your own Data Hub."},"features/settings/settings-device-info":{"id":"features/settings/settings-device-info","title":"Device Info","description":"The Device info section will provide you with details regarding general information about the Data Hub currently being accessed.  The below shows all of the information available to a user who has the Owner or Manager role for the Data Hub.  Users with the Member role will show less information, with some settings being unavailable."},"features/settings/settings-disk-management":{"id":"features/settings/settings-disk-management","title":"Disk Management","description":"The hard disk drives (HDD), solid-state drives (SSD) and any externally-connected drives installed or connected to your Data Hub are available for configuration in Disk Management.  DASSET supports the ability to configure your drives in a way for optimal performance and redundancy using data storage virtualization technology known as RAID."},"features/settings/settings-disk-self-test":{"id":"features/settings/settings-disk-self-test","title":"Disk Self-Test","description":"Hard Disk Drives (HDD) are mechanical storage devices, and as such, will eventually fail if not replaced.  Known as the Mean Time Between Failure (MTBF), most HDDs have a MTBF between 300,000 and 1,200,000 hours.  When a HDD begins to experience failure due to MTBF, you may see things such as failure to read or write files, or mechanical clicking sounds coming from your HDD."},"features/settings/settings-disk-sleep":{"id":"features/settings/settings-disk-sleep","title":"Disk Sleep","description":"In the Disk Self-Test article, it was explained that disk drives can eventually fail after prolonged use.  A way to extend the life (MTBF) of the disks installed in your Data Hub is to use the Disk Sleep feature to put your disks into a low-power state when your Data Hub is not typically in use.  Your Data Hub is still powered-on and operating normally.  If the Data Hub needs to access data on the disks when they are in the sleep mode, the system will automatically wake-up the disks to read or write data as necessary."},"features/settings/settings-hardware-status":{"id":"features/settings/settings-hardware-status","title":"Hardware Status","description":"Viewing the specific devices of your Data Hub, such as CPU, memory and storage can be found in Hardware Status."},"features/settings/settings-home":{"id":"features/settings/settings-home","title":"Settings Screen","description":"After logging into your account and connecting to a Data Hub, you can access the Settings of the Data Hub to control specific behavior and hardware features of the device.  You can access Settings by clicking on the Settings icon on the DASSET navigation bar."},"features/settings/settings-lan-settings":{"id":"features/settings/settings-lan-settings","title":"LAN Settings","description":"Viewing and configuring how your DASSET Data Hub is accessible on your home or business network is available through the LAN Settings screen."},"features/settings/settings-member-management":{"id":"features/settings/settings-member-management","title":"Member Management","description":"The Member Management screen shows all current users who have joined your Data Hub, as well as the Roles and Permissions they have.  From this screen, Owners and Managers have the ability to modify permissions of users as well as having the ability to add additional users to the Data Hub."},"features/settings/settings-power-management":{"id":"features/settings/settings-power-management","title":"Power Management","description":"There are times when you may want your DASSET Data Hub to be rebooted, or turned completely off for either saving power, upgrading hardware or applying updates to the system, which is accomplished through Power Management."},"features/settings/settings-security-settings":{"id":"features/settings/settings-security-settings","title":"Security Settings","description":"If you want to add additional security to your DASSET Data Hub, you can do so in the Security Settings screen."},"features/settings/settings-share-device":{"id":"features/settings/settings-share-device","title":"Share Device","description":"DASSET Data Hubs provide a simple, yet secure, method for sharing your data with others.  Share Device gives users with the Owner or Manager role to invite a user to join the Data Hub.  When a user accepts an invite to join a Data Hub, they have access to files and applications on the device, based on the roles and permissions they have been assigned."},"getting-started/intro":{"id":"getting-started/intro","title":"Introduction","description":"Our Data Dilemma","sidebar":"DocsSidebar"},"getting-started/introOLD":{"id":"getting-started/introOLD","title":"Introduction","description":"Our data dilemma"},"how-to/getting-started/dasset-app-install":{"id":"how-to/getting-started/dasset-app-install","title":"Install the DASSET app","description":"The DASSET application is the way you access the data and applications on your DASSET Data Hub, or a Data Hub that has been shared with you by other Data Hub users.  Once you have the DASSET application installed, you can configure alternative ways to access your files, such as using SAMBA which allows you to mount your Data Hub as a mapped drive in Windows or MacOS."},"how-to/getting-started/device-set-up":{"id":"how-to/getting-started/device-set-up","title":"Set-up your DASSET Data Hub","description":"Congratulations on the purchase of your DASSET Data Hub!  In this article, you will be guided through the steps of initially setting-up and connecting to your Data Hub using the DASSET application."},"oem-odm/oem-opportunity":{"id":"oem-odm/oem-opportunity","title":"DASSET for OEMs","description":"A \\"Blue Ocean\\" Opportunity in Smart Storage","sidebar":"DocsSidebar"},"oem-odm/oem-software-platform":{"id":"oem-odm/oem-software-platform","title":"DASSET Software Platform","description":"Overview","sidebar":"DocsSidebar"},"privacy-policy/privacy-policy":{"id":"privacy-policy/privacy-policy","title":"Privacy Policy","description":"Update Date: February 26, 2024","sidebar":"DocsSidebar"},"troubleshooting/connectivity":{"id":"troubleshooting/connectivity","title":"Connectivity Errors","description":"","sidebar":"DocsSidebar"},"user-guide/mobile":{"id":"user-guide/mobile","title":"Android & iOS","description":"This document is intended to help users quickly understand the full","sidebar":"DocsSidebar"},"user-guide/pc-mac":{"id":"user-guide/pc-mac","title":"Windows & macOS","description":"This document is intended to help users quickly understand the full","sidebar":"DocsSidebar"}}}}')}}]);